// [ spectate.js 파일 ]

// [중요!] 학생의 render.com 서버 주소로 변경하세요
const SERVER_URL = "wss://pikavolley-relay-server.onrender.com";

// HTML 요소 가져오기
const roomIdInput = document.getElementById("room-id-input");
const connectButton = document.getElementById("connect-button");
const logOutput = document.getElementById("log-output");

let ws = null; // WebSocket 객체를 저장할 변수

function log(message, color = "#000") {
    console.log(message); // F12 콘솔에도 출력
    logOutput.innerHTML += `<span style="color: ${color};">${message}</span>\n`;
    logOutput.scrollTop = logOutput.scrollHeight; // 항상 아래로 스크롤
}

connectButton.addEventListener("click", () => {
    if (ws) {
        log("이미 연결되었습니다. 새로고침 후 다시 시도하세요.", "#FF0000");
        return;
    }
    if (!(roomIdInput instanceof HTMLInputElement)) {
        alert("치명적 오류: Room ID 입력창(input)을 찾을 수 없습니다.");
        return;
    }
    const roomId = roomIdInput.value.trim(); // .trim()으로 공백 제거
    if (!roomId) {
        alert("Room ID를 입력하세요.");
        return;
    }

    const connectUrl = `${SERVER_URL}/${roomId}`;
    log(`Connecting to: ${connectUrl}`, "#888");
    
    // 1. WebSocket 연결 생성
    ws = new WebSocket(connectUrl);
    if (!(connectButton instanceof HTMLButtonElement)) {
        alert("치명적 오류: 접속 버튼(button)을 찾을 수 없습니다.");
        return;
    }
    connectButton.disabled = true;
    connectButton.textContent = "연결 중...";

    // 2. 연결 성공 시
    ws.onopen = () => {
        log(`[${roomId}] WebSocket 연결 성공!`, "#00AA00");
        
        // 3. 서버에 'watch' 메시지 전송 (관전자 등록)
        ws.send(JSON.stringify({ type: "watch" }));
        log("'watch' 메시지를 서버로 전송했습니다.", "#0000FF");
        connectButton.textContent = "연결됨";
    };

    // 4. [핵심] 서버로부터 메시지 수신 시
    ws.onmessage = (event) => {
        try {
            const data = JSON.parse(event.data);
            
            // [성공] 서버에서 받은 데이터를 콘솔에 그대로 출력
            if (data.type === "replay_pack") {
                // 이것이 학생이 말한 'input 행렬' (전체 팩)
                log(`%c[Replay Pack] 수신: 총 ${data.pack.inputs.length}개의 누적된 입력값 받음.`, "#00FFFF");
                console.log("[Replay Pack]", data); // 콘솔에는 전체 객체 덤프
            } else if (data.type === "live_input") {
                // 이것이 실시간 'input'
                log(`%c[Live Input] 수신: ${data.value}`, "#00FF00");
            } else {
                // (live_options, live_chat 등)
                log(`[Server Message] 수신: ${data.type}`, "#CCC");
                console.log("[Server Message]", data);
origin
            }
            
        } catch (e) {
            log(`[Error] Failed to parse server message: ${e.message}`, "#FF0000");
            console.error("Failed to parse server message:", e, event.data);
        }
    };

    // 5. 연결 종료 시
    ws.onclose = (event) => {
        log(`[${roomId}] WebSocket 연결 종료. (Code: ${event.code})`, "#FF0000");
        ws = null; // 연결 초기화
        connectButton.disabled = false;
        connectButton.textContent = "접속";
    };

    // 6. 에러 발생 시
    ws.onerror = (error) => {
        log(`[Error] WebSocket 오류 발생. F12 콘솔을 확인하세요.`, "#FF0000");
        console.error("WebSocket Error:", error);
        ws = null;
        connectButton.disabled = false;
        connectButton.textContent = "접속";
    };
});